use crate::money::{money, Money};

/// What a put is worth at expiry, and where it breaks even.
///
/// `None` for `max_loss` never appears here: the loss is the premium, always, which is the reason
/// this vehicle exists.
pub fn put_payoff(strike: Money, premium: Money, contracts: i64, at: Money) -> Money {
    let intrinsic = (strike.minor - at.minor).max(0);
    money((intrinsic - premium.minor) * 100 * contracts, strike.currency)
}
